    quads = {}
    for name, rs, cs in [('tl', range(h), range(h)), ('tr', range(h), range(h, 2*h)),
                         ('bl', range(h, 2*h), range(h)), ('br', range(h, 2*h), range(h, 2*h))]:
        quads[name] = [[grid[r][c] for c in cs] for r in rs]
    solids = {name: q[0][0] for name, q in quads.items()
              if all(v == q[0][0] and v != 0 for row in q for v in row)}
    base_name, base = next(iter(solids.items()))
    best = None
    for name, q in quads.items():
        colors = {v for row in q for v in row if v}
        if len(colors) < 2:
            continue
        for kind in ('checker0', 'checker1', 'rows', 'cols'):
            groups = {}
            for r in range(h):
                for c in range(h):
                    if kind.startswith('checker'):
                        k = (r + c) % 2
                    elif kind == 'rows':
                        k = r % 2
                    else:
                        k = c % 2
                    groups.setdefault(k, []).append(q[r][c])
            tile_colors = {}
            mismatches = 0
            for k, vals in groups.items():
                nz = [v for v in vals if v]
                if nz:
                    counts = {v: nz.count(v) for v in set(nz)}
                    color = max(counts, key=counts.get)
                    tile_colors[k] = color
                    mismatches += len(nz) - counts[color]
                else:
                    tile_colors[k] = 0
            if len(set(tile_colors.values())) < 2:
                continue
            score = -mismatches
            if best is None or score > best[0]:
                tile = []
                for r in range(h):
                    row = []
                    for c in range(h):
                        if kind.startswith('checker'):
                            k = (r + c) % 2
                        elif kind == 'rows':
                            k = r % 2
                        else:
                            k = c % 2
                        row.append(tile_colors[k] or base)
                    tile.append(row)
                best = (score, name, tile)
    _, target_name, tile = best
    diagonal = ((target_name[0] != base_name[0]) and (target_name[1] != base_name[1]))
    nx = 1 if diagonal else 4
    ny = 4
    return [[tile[r % h][c % h] for c in range(h * nx)] for r in range(h * ny)]
